@mcp.tool()
def run_static_analysis(file_path: str) -> str:
    """Run static analysis on a file and return report."""
    if not file_path.endswith(".py"):
        return "Error: Only Python files supported"
    # Execute linter and return clean result
    return "0 errors, 0 warnings"

if __name__ == "__main__":
    mcp.run()", "language": "python"}, "quiz": null, "notes": "Here is a worked example of defining an MCP server using FastMCP in Python. Notice how parameter types and docstrings serve as the specification for the AI agent. The function signature and docstring tell the LLM what inputs are required and what the tool accomplishes.", "los": ["CO1.LO2"], "sources": [], "minutes": 7}, {"kind": "example", "title": "Configuring Tool Workspaces without Warnings", "bullets": ["Configuration files map local tool commands into the agent's active workspace.", "Environmental variables and paths must be set explicitly to satisfy static analysis.", "Passing static analysis verification requires clean type annotations and valid JSON syntax."], "figure": {"kind": "code", "caption": "Workspace Agent Tool Configuration", "code": "{
